// Generated by build_site.py from data/glossary.csv and data/abbreviations.csv: popup text for terms.
window.SF_TERMS = {"antenna-3":{"t":"Antenna 3","f":"Flagellomere 1 (f1)","s":"AIII; antennal segment 3","x":"both","d":"First flagellomere, the first long segment of the antenna after scape and pedicel. Older keys number antennal segments from the scape, so &#x27;antenna 3&#x27; = f1, &#x27;antenna 4&#x27; = f2, &#x27;antenna 5&#x27; = f3. Lengths and ratios to the labrum are used in many couplets.","g":"glossary.html#antenna-3"},"ascoid":{"t":"Ascoid","f":"","s":"Geniculated spine","x":"both","d":"Hyaline sensory rod on the flagellomeres. Number per segment (antennal formula), length relative to the segment (e.g. asc/f2) and presence of spurs are diagnostic (e.g. <i>S. gemmea</i> and <i>S. raynali</i> have spurred ascoids).","g":"glossary.html#ascoid"},"papilla":{"t":"Papilla","f":"","s":"Hirsute gland; sensorial papilla","x":"both","d":"Small sensillum on the flagellomeres. Its presence on antenna 5 (f3) separates <i>P. argentipes</i> from <i>P. philippinensis</i> in Lewis 1978.","g":"glossary.html#papilla"},"newstead-s-sensilla":{"t":"Newstead&#x27;s sensilla","f":"","s":"Newstead&#x27;s spines; Newstead scales; hyaline sensilla; peg sensilla","x":"both","d":"Club-shaped sensilla on palpal segment 3 (sometimes 2). Their arrangement is used by Quate 1962 and Lewis 1978.","g":"glossary.html#newstead-s-sensilla"},"palpal-formula":{"t":"Palpal formula","f":"","s":"","x":"both","d":"The sequence of palp segments from shortest to longest, e.g. 1-2-4-3-5.","g":"glossary.html#palpal-formula"},"labrum":{"t":"Labrum","f":"Labrum-epipharynx","s":"","x":"both","d":"The dorsal mouthpart. Its length is the standard against which antenna 3 and wing length are compared.","g":"glossary.html#labrum"},"cibarium":{"t":"Cibarium","f":"","s":"Buccal cavity","x":"both","d":"The chamber behind the mouthparts. Its armature (teeth, sclerotized area, arch) is the most-used character in female <i>Sergentomyia</i> keys.","g":"glossary.html#cibarium"},"hind-teeth":{"t":"Hind teeth","f":"Posterior teeth","s":"Horizontal teeth; cibarial teeth; main teeth","x":"female","d":"The main transverse row of teeth at the hind end of the cibarium. Counts and row shape (concave, convex, straight) are key characters.","g":"glossary.html#hind-teeth"},"fore-teeth":{"t":"Fore teeth","f":"Anterior teeth","s":"Vertical teeth; erect teeth; denticles","x":"female","d":"Smaller teeth in one or more rows in front of the hind teeth. Number of rows (e.g. &#x27;three rows of fore teeth&#x27;) is used in <i>Neophlebotomus</i> couplets.","g":"glossary.html#fore-teeth"},"pigment-patch":{"t":"Pigment patch","f":"Sclerotized area","s":"Pigmented area; pigment belt; plage pigmentée","x":"female","d":"Darkened area of the cibarium in front of the tooth row. Its shape (bifid tip, anterior projection, narrow/linear) is diagnostic.","g":"glossary.html#pigment-patch"},"cibarial-arch":{"t":"Cibarial arch","f":"Sclerotized arch","s":"Chitinous arch","x":"female","d":"Arched sclerite at the front of the cibarium; the distance between arch and teeth is used in Lewis 1978 couplet 168.","g":"glossary.html#cibarial-arch"},"notch":{"t":"Notch","f":"Notch of the ventral plate","s":"","x":"female","d":"A median notch at the hind end of the cibarial ventral plate; characteristic of the <i>S. babu</i> series.","g":"glossary.html#notch"},"pharynx":{"t":"Pharynx","f":"","s":"","x":"both","d":"Tube behind the cibarium. The hind part may carry an armature of teeth, scales, ridges or spicules, which is key for <i>Phlebotomus</i> subgenera and <i>Parrotomyia</i>.","g":"glossary.html#pharynx"},"pharyngeal-armature":{"t":"Pharyngeal armature","f":"Pharyngeal teeth","s":"Spines of pharynx","x":"both","d":"The teeth, scales or ridges lining the hind part of the pharynx.","g":"glossary.html#pharyngeal-armature"},"r2-r2-3":{"t":"R2/R2+3","f":"Wing index alpha/beta","s":"Wing index","x":"both","d":"Ratio of the length of vein section R2 (alpha) to R2+3 (beta). &#x27;R1 overlap&#x27; is the distance by which the tip of R1 passes the fork of R2+3.","g":"glossary.html#r2-r2-3"},"abdominal-tergites-2-6":{"t":"Abdominal tergites 2-6","f":"Tergites II-VI","s":"","x":"both","d":"In <i>Phlebotomus</i> the hairs on tergites 2-6 are erect and arise from large sockets; in <i>Sergentomyia</i> they are recumbent with small sockets. This is couplet 1 of most keys.","g":"glossary.html#abdominal-tergites-2-6"},"spermatheca":{"t":"Spermatheca","f":"","s":"Body of spermatheca","x":"female","d":"Paired sperm-storage organ. Segmented (ringed), striated, smooth capsule or tubular forms define subgenera.","g":"glossary.html#spermatheca"},"head-of-spermatheca":{"t":"Head of spermatheca","f":"Terminal knob","s":"Head; apical segment","x":"female","d":"The apical part of the spermatheca, sometimes on a narrow neck.","g":"glossary.html#head-of-spermatheca"},"spermathecal-ducts":{"t":"Spermathecal ducts","f":"Individual and common spermathecal ducts","s":"Ducts","x":"female","d":"Each spermatheca opens into an individual duct; these join into a common duct. Their lengths separate <i>P. shadenae</i>, <i>P. stantoni</i> and <i>P. hoepplii</i>.","g":"glossary.html#spermathecal-ducts"},"genital-furca":{"t":"Genital furca","f":"Genital fork","s":"Genital furca","x":"female","d":"Sclerite of the female genital chamber.","g":"glossary.html#genital-furca"},"coxite":{"t":"Coxite","f":"Gonocoxite","s":"Basistyle; basimere; coxite","x":"male","d":"Basal segment of the male clasper. Its basal process or tuft of hairs (brush) is diagnostic.","g":"glossary.html#coxite"},"style":{"t":"Style","f":"Gonostyle","s":"Dististyle; distimere; style","x":"male","d":"Distal segment of the clasper. Number and position of its spines (terminal, subterminal, near middle) are used at genus and subgenus level; <i>Sergentomyia</i> has an accessory seta.","g":"glossary.html#style"},"accessory-seta":{"t":"Accessory seta","f":"Accessory seta of gonostyle","s":"Setiform spine","x":"male","d":"Fine seta on the gonostyle of <i>Sergentomyia</i> (absent in <i>Phlebotomus</i>).","g":"glossary.html#accessory-seta"},"paramere":{"t":"Paramere","f":"","s":"Intermediate appendage; clasper; claspette","x":"male","d":"Middle appendage of the male genitalia. Number of lobes (simple, bilobed, trilobed) separates <i>Euphlebotomus</i> and <i>Anaphlebotomus</i> species.","g":"glossary.html#paramere"},"aedeagus":{"t":"Aedeagus","f":"Parameral sheath","s":"Aedeagal sheath; aedeagus; penis; gubernaculum","x":"male","d":"The sclerotized sheath through which the genital filaments emerge (older keys call it the aedeagus). Its tip shape is used in <i>Parrotomyia</i> and <i>Larroussius</i>.","g":"glossary.html#aedeagus"},"genital-filaments":{"t":"Genital filaments","f":"Aedeagal ducts","s":"Genital filaments; ejaculatory ducts; penal filaments","x":"male","d":"Paired ducts leaving the sperm pump. Their length relative to the pump is diagnostic (e.g. <i>P. shadenae</i> versus <i>P. stantoni</i>).","g":"glossary.html#genital-filaments"},"genital-pump":{"t":"Genital pump","f":"Sperm pump","s":"Ejaculatory pump; pompetta","x":"male","d":"Internal pump that the genital filaments leave. Used as the unit for filament length.","g":"glossary.html#genital-pump"},"surstyle":{"t":"Surstyle","f":"Epandrial lobe","s":"Lateral lobe; surstyle; lower gonapophysis","x":"male","d":"Lobe beside the gonocoxite. Terminal spines on it occur in subgenus <i>Phlebotomus</i>.","g":"glossary.html#surstyle"},"intra-abdominal-rods":{"t":"Intra-abdominal rods","f":"Hypandrial apodemes","s":"Sclerotized rods","x":"male","d":"Paired rods next to the sperm pump; characteristic of <i>Idiophlebotomus</i>.","g":"glossary.html#intra-abdominal-rods"},"anepimeron-scales":{"t":"Anepimeron scales","f":"Anepimeral scales","s":"","x":"both","d":"Scales on the anepimeron (thorax side); counted in the Lewis 1987 <i>Grassomyia</i> key.","g":"glossary.html#anepimeron-scales"},"trumpet-glands":{"t":"Trumpet glands","f":"","s":"glandes en trompettes; trumpet-shaped glands","x":"male","d":"Small trumpet-shaped glandular structures on the abdominal tergites of males of <i>Chinius</i>: 40-50 on the antero-dorsal parts of tergites 4 and 5 in <i>Ch. barbazani</i>, also present in <i>Ch. junlianensis</i>; Depaquit et al. (2006) include them in the definition of the genus.","g":"glossary.html#trumpet-glands"},"a-antenna":{"t":"antenna","f":"","d":"Jointed sensory appendage of the head: scape, pedicel and 14 flagellomeres (fI–fXIV). Older keys number the segments from the scape, so antenna 3 = fI, antenna 4 = fII, antenna 5 = fIII.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-sc":{"t":"sc","f":"scape","d":"First (basal) segment of the antenna, short and cup-shaped.","g":"glossary.html#a-sc","l":""},"a-pe":{"t":"pe","f":"pedicel","d":"Second segment of the antenna, globular, between the scape and the first flagellomere.","g":"glossary.html#a-pe","l":""},"a-fi":{"t":"fI","f":"1st flagellomere","d":"The first long antennal segment after scape and pedicel = &#x27;antenna 3&#x27; (A3, AIII) of older keys. Its length, often compared with the labrum, is used in many couplets.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-fii":{"t":"fII","f":"2nd flagellomere","d":"= &#x27;antenna 4&#x27; of older keys. Ascoid length is often expressed relative to it (asc/f2).","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-fxi-xiv":{"t":"fXI–fXIV","f":"apical flagellomeres","d":"The last four flagellomeres, shorter than the basal ones. Presence of ascoids and papillae on them is used in some keys.","g":"glossary.html#ascoid","l":"Ascoid"},"a-asc-f2":{"t":"asc/f2","f":"ascoid length / 2nd flagellomere length","d":"Ratio of the length of the ascoid to the length of flagellomere 2 (antenna 4).","g":"glossary.html#ascoid","l":"Ascoid"},"a-a3-e":{"t":"A3/E","f":"antenna 3 / labrum (epipharynx) ratio","d":"Length of flagellomere 1 (antenna 3) divided by the length of the labrum-epipharynx (E). A value below 1 means antenna 3 is shorter than the labrum.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-palp":{"t":"palp","f":"maxillary palp (palpus)","d":"Five-segmented sensory appendage beside the proboscis (p1–p5). The order of the segments by length gives the palpal formula, e.g. 1-2-4-3-5.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p1":{"t":"p1","f":"1st palpal segment","d":"Basal segment of the palp, usually the shortest.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p2":{"t":"p2","f":"2nd palpal segment","d":"Second segment of the palp.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p3":{"t":"p3","f":"3rd palpal segment","d":"Third segment of the palp; carries the Newstead&#x27;s sensilla.","g":"glossary.html#newstead-s-sensilla","l":"Newstead&#x27;s sensilla"},"a-p4":{"t":"p4","f":"4th palpal segment","d":"Fourth segment of the palp, often short.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p5":{"t":"p5","f":"5th palpal segment","d":"Distal segment of the palp, usually the longest; whether it is the longest is used in some keys.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-eye":{"t":"eye","f":"compound eye","d":"Large compound eye on each side of the head. Its size and the distance between the eyes (interocular distance) are measured in descriptions.","g":"glossary.html#a-eye","l":""},"a-iod":{"t":"ioD","f":"interocular distance","d":"Narrowest distance between the two compound eyes across the frons.","g":"glossary.html#a-iod","l":""},"a-cl":{"t":"cl","f":"clypeus","d":"Sclerite on the front of the head between the antennae, above the base of the labrum.","g":"glossary.html#a-cl","l":""},"a-hel":{"t":"heL","f":"head length","d":"Measurement: length of the head from the vertex to the lower edge of the clypeus.","g":"glossary.html#a-hel","l":""},"a-hw":{"t":"hW","f":"head width","d":"Measurement: greatest width of the head across the eyes.","g":"glossary.html#a-hw","l":""},"a-el":{"t":"eL","f":"eye length","d":"Measurement: greatest length of the compound eye.","g":"glossary.html#a-el","l":""},"a-ew":{"t":"eW","f":"eye width","d":"Measurement: width of the compound eye.","g":"glossary.html#a-ew","l":""},"a-cll":{"t":"clL","f":"clypeus length","d":"Measurement: length of the clypeus.","g":"glossary.html#a-cll","l":""},"a-fil":{"t":"fIL","f":"1st flagellomere length","d":"Measurement: length of flagellomere 1 (antenna 3), compared with the labrum or other segments in many keys.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-pl":{"t":"pL","f":"palpus length","d":"Measurement: total length of the palp (p1–p5).","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-le":{"t":"le","f":"labrum-epipharynx","d":"Upper blade of the proboscis; its length (E) is the standard for comparing antenna 3 and palpal segments.","g":"glossary.html#labrum","l":"Labrum"},"a-md":{"t":"md","f":"mandible","d":"Paired blade-like mouthparts with fine teeth, used by females to cut the skin.","g":"glossary.html#a-md","l":""},"a-hy":{"t":"hy","f":"hypopharynx","d":"Median blade of the proboscis that carries the salivary channel.","g":"glossary.html#a-hy","l":""},"a-lb":{"t":"lb","f":"labium","d":"Lower lip that sheathes the other mouthparts and ends in two labella.","g":"glossary.html#a-lb","l":""},"a-ml":{"t":"ml","f":"maxillary lacinia","d":"Blade of the maxilla, toothed at the tip in blood-feeding females.","g":"glossary.html#a-ml","l":""},"a-pha":{"t":"pha","f":"pharynx","d":"Muscular tube behind the cibarium; its shape and armature are diagnostic.","g":"glossary.html#pharynx","l":"Pharynx"},"a-pht":{"t":"pht","f":"pharyngeal teeth","d":"Teeth, spines or ridges on the posterior part of the pharynx (pharyngeal armature).","g":"glossary.html#pharyngeal-armature","l":"Pharyngeal armature"},"a-cic":{"t":"cic","f":"cibarial chamber","d":"Chamber at the base of the mouthparts, in front of the pharynx, that carries the cibarial armature.","g":"glossary.html#cibarium","l":"Cibarium"},"a-ptt":{"t":"ptt","f":"posterior teeth","d":"Row of large horizontal teeth at the back of the cibarium (&#x27;hind teeth&#x27; of older keys).","g":"glossary.html#hind-teeth","l":"Hind teeth"},"a-antt":{"t":"antt","f":"anterior teeth","d":"Small vertical teeth in front of the posterior teeth (&#x27;fore teeth&#x27; of older keys).","g":"glossary.html#fore-teeth","l":"Fore teeth"},"a-ltt":{"t":"ltt","f":"lateral teeth","d":"Teeth at the sides of the cibarium, outside the main row.","g":"glossary.html#cibarium","l":"Cibarium"},"a-pp":{"t":"pp","f":"posterior protuberance","d":"Projection at the back of the cibarium, near the posterior bridge.","g":"glossary.html#cibarium","l":"Cibarium"},"a-psbr":{"t":"psbr","f":"posterior bridge","d":"Sclerotized bridge at the junction of cibarium and pharynx.","g":"glossary.html#cibarium","l":"Cibarium"},"a-scarc":{"t":"scarc","f":"sclerotized arch","d":"Chitinous arch crossing the cibarium; complete or incomplete in different groups.","g":"glossary.html#cibarial-arch","l":"Cibarial arch"},"a-scare":{"t":"scare","f":"sclerotized area","d":"Pigmented (sclerotized) patch in the middle of the cibarium; its shape and colour are used in keys.","g":"glossary.html#pigment-patch","l":"Pigment patch"},"a-latsc":{"t":"latsc","f":"lateral sclerite","d":"Sclerotized strip along each side of the cibarium.","g":"glossary.html#cibarium","l":"Cibarium"},"a-r1-r5":{"t":"R1–R5","f":"radial veins","d":"The five branches of the radius, numbered from the front margin of the wing.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-m1-m4":{"t":"M1–M4","f":"medial veins","d":"The four branches of the media, behind the radial veins.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-rm":{"t":"rm","f":"radio-medial cross-vein","d":"Short cross-vein joining radius and media near the wing base.","g":"glossary.html#a-rm","l":""},"a-alpha":{"t":"α (alpha)","f":"length of R2","d":"Wing index α: length of vein R2 from its fork to the wing margin.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-beta":{"t":"β (beta)","f":"length of R2+3","d":"Wing index β: length of the stem R2+3, from the fork of R2+3+4 to the fork of R2 and R3. Keys use the ratio α/β (R2/R2+3).","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-gamma":{"t":"γ (gamma)","f":"length of R2+3+4","d":"Wing index γ: length of the stem R2+3+4, from the r-m cross-vein to its fork.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-delta":{"t":"δ (delta)","f":"R1 tip to R2+3 fork","d":"Wing index δ: distance between the tip of R1 and the fork of R2+3; positive when R1 ends beyond the fork.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-epsilon":{"t":"ε (epsilon)","f":"length of R3","d":"Wing index ε: length of vein R3.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-theta":{"t":"θ (theta)","f":"length of R4","d":"Wing index θ: length of vein R4 from the fork of R2+3+4 to the wing margin.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-pi":{"t":"π (pi)","f":"distance between forks","d":"Wing index π: distance between the fork of R2+3+4 and the fork of M1+2.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-r2":{"t":"R2","f":"radial vein 2","d":"Second branch of the radius; its length is wing index α.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-wing-length":{"t":"length","f":"wing length","d":"Measurement: from the wing base to the tip.","g":"glossary.html#a-wing-length","l":""},"a-wing-width":{"t":"width","f":"wing width","d":"Measurement: greatest width of the wing.","g":"glossary.html#a-wing-width","l":""},"a-terg":{"t":"terg","f":"tergite","d":"Dorsal plate of an abdominal segment (numbered 1st–10th).","g":"glossary.html#abdominal-tergites-2-6","l":"Abdominal tergites 2-6"},"a-st":{"t":"st","f":"sternite","d":"Ventral plate of an abdominal segment.","g":"glossary.html#a-st","l":""},"a-cercus":{"t":"cercus","f":"cercus (pl. cerci)","d":"Paired terminal appendage at the tip of the abdomen, above the 10th sternite.","g":"glossary.html#a-cercus","l":""},"a-terminal-knob":{"t":"terminal knob","f":"terminal knob (head) of spermatheca","d":"Small knob at the apex of the spermatheca, often set in a neck; its shape is used in keys.","g":"glossary.html#head-of-spermatheca","l":"Head of spermatheca"},"a-individual-duct":{"t":"individual duct","f":"individual spermathecal duct","d":"Duct leading from each spermatheca; joins its partner to form the common duct.","g":"glossary.html#spermathecal-ducts","l":"Spermathecal ducts"},"a-common-duct":{"t":"common duct","f":"common spermathecal duct","d":"Short duct formed by the union of the two individual ducts.","g":"glossary.html#spermathecal-ducts","l":"Spermathecal ducts"},"a-stem":{"t":"stem","f":"fork stem","d":"Median stem of the genital furca (genital fork).","g":"glossary.html#genital-furca","l":"Genital furca"},"a-furca":{"t":"furca","f":"genital furca","d":"Fork-shaped sclerite of the 9th segment in females, supporting the genital opening.","g":"glossary.html#genital-furca","l":"Genital furca"},"a-gon":{"t":"gon","f":"gonopod","d":"Small appendage of the 8th segment in females (8th gonopod).","g":"glossary.html#a-gon","l":""},"a-insula":{"t":"insula","f":"","d":"Sclerotized area of the 8th segment near the genital opening in females.","g":"glossary.html#a-insula","l":""},"a-gonostylus":{"t":"gonostylus","f":"gonostyle (style)","d":"Distal segment of the male clasper, carrying the large spines.","g":"glossary.html#style","l":"Style"},"a-gonocoxite":{"t":"gonocoxite","f":"gonocoxite (coxite)","d":"Basal segment of the male clasper.","g":"glossary.html#coxite","l":"Coxite"},"a-paramere":{"t":"paramere","f":"","d":"Paired median appendage of the male genitalia, often with setae and lobes.","g":"glossary.html#paramere","l":"Paramere"},"a-parameral-sheath":{"t":"parameral sheath","f":"parameral sheath (aedeagus)","d":"Sclerotized sheath around the end of the aedeagal ducts.","g":"glossary.html#aedeagus","l":"Aedeagus"},"a-aedeagal-ducts":{"t":"aedeagal ducts","f":"aedeagal ducts (genital filaments)","d":"Paired ducts from the sperm pump to the tip of the parameral sheath; their length and tip shape are diagnostic.","g":"glossary.html#genital-filaments","l":"Genital filaments"},"a-sperm-pump":{"t":"sperm pump","f":"sperm pump (genital pump)","d":"Bulb-shaped pump inside the abdomen that pushes sperm along the aedeagal ducts.","g":"glossary.html#genital-pump","l":"Genital pump"},"a-ejac-apodeme":{"t":"ejaculatory apodeme","f":"","d":"Rod-like apodeme attached to the sperm pump.","g":"glossary.html#genital-pump","l":"Genital pump"},"a-epandrial-lobe":{"t":"epandrial lobe","f":"epandrial lobe (surstyle)","d":"Paired lateral lobe below the clasper (&#x27;surstyle&#x27; or &#x27;lateral lobe&#x27; of older keys).","g":"glossary.html#surstyle","l":"Surstyle"},"a-gonostyle-spines":{"t":"spines of gonostyle","f":"apical, external and internal spines","d":"Large spines of the gonostyle. Their number and position (apical, upper and lower external, internal) are key characters for subgenera.","g":"glossary.html#style","l":"Style"},"a-ste9":{"t":"9th ste","f":"9th sternite","d":"Ventral plate of the 9th segment of the male.","g":"glossary.html#a-ste9","l":""},"a-ter10":{"t":"10th ter","f":"10th tergite","d":"Dorsal plate of the 10th segment of the male.","g":"glossary.html#a-ter10","l":""},"a-ste10":{"t":"10th ste","f":"10th sternite","d":"Ventral plate of the 10th segment of the male.","g":"glossary.html#a-ste10","l":""},"a-f":{"t":"f","f":"fold","d":"Transverse fold (ridge) of the pharynx wall, seen in the posterior part of the pharynx.","g":"glossary.html#pharynx","l":"Pharynx"}};
